/* From Uiverse.io by Javierrocadev - Source: twitter.com - Tags: twitter, card, card hover */
.__UIV_SCOPE__ .card {
  width: 350px;
  height: 350px;
  background: #E8EAEA;
  border-radius: 15px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.__UIV_SCOPE__ .title, .__UIV_SCOPE__ .more {
  padding: 10px 15px;
}

.__UIV_SCOPE__ .user {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  padding: 10px 15px;
}

.__UIV_SCOPE__ .user__content {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-grow: 1;
}

.__UIV_SCOPE__ .user__container {
  display: flex;
  flex-direction: column;
}

.__UIV_SCOPE__ .title {
  font-weight: 900;
  font-size: 1.3em;
}

.__UIV_SCOPE__ .name {
  font-weight: 800;
}

.__UIV_SCOPE__ .username {
  font-size: .9em;
  color: #64696e;
}

.__UIV_SCOPE__ .image {
  width: 60px;
  height: 60px;
  background: rgb(22,19,70);
  background: linear-gradient(295deg, rgba(22,19,70,1) 41%, rgba(89,177,237,1) 100%);
  border-radius: 50%;
  margin-right: 15px;
}

.__UIV_SCOPE__ .follow {
  border: none;
  border-radius: 25px;
  background-color: #0f1113;
  color: white;
  padding: 8px 15px;
  font-weight: 700;
}

.__UIV_SCOPE__ .more {
  display: block;
  text-decoration: none;
  color: rgb(29, 155, 240);
  font-weight: 800;
}

.__UIV_SCOPE__ .user:hover {
  background-color: #b3b6b6;
}

.__UIV_SCOPE__ .more:hover {
  background-color: #b3b6b6;
  border-radius: 0px 0px 15px 15px;
}

.__UIV_SCOPE__ .follow:hover {
  background-color: #2c3136;
}
